"use client";

import { useCurrentFrame, useVideoConfig } from "remotion";

export type BentoTheme = "light" | "dark";

export interface InfiniteBentoPanProps {
  /** Fraction of the full diagonal traversal covered over the duration (0–1). */
  panSpeed?: number;
  accentColor?: string;
  theme?: BentoTheme;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

export const SUPER_W = 3500;
export const SUPER_H = 2500;
export const PAD = 80;
export const GAP = 40;
export const ROW_H = 300;

const TONES = {
  danger: "#F04438",
  warning: "#F79009",
  success: "#12B76A",
} as const;

interface ThemeTokens {
  card: string;
  border: string;
  text: string;
  muted: string;
  skeleton: string;
  skeletonSoft: string;
  /** "r,g,b" triplet of the surrounding canvas, used by the edge vignette. */
  vignetteRgb: string;
}

export const BENTO_THEMES: Record<BentoTheme, ThemeTokens> = {
  light: {
    card: "#FFFFFF",
    border: "#E4E7EC",
    text: "#101828",
    muted: "#667085",
    skeleton: "#E4E7EC",
    skeletonSoft: "#F2F4F7",
    vignetteRgb: "250,250,250",
  },
  dark: {
    card: "#141417",
    border: "#26272B",
    text: "#FAFAFA",
    muted: "#A1A1AA",
    skeleton: "#26272B",
    skeletonSoft: "#1D1D21",
    vignetteRgb: "10,10,11",
  },
};

type CardKind =
  | "chart"
  | "bars"
  | "counter"
  | "stat"
  | "code"
  | "alerts"
  | "oncall";

interface ListItem {
  tone: keyof typeof TONES;
  text: string;
  meta: string;
}

interface Person {
  initials: string;
  name: string;
  meta: string;
  active?: boolean;
}

export interface RowCardDef {
  w: number;
  kind: CardKind;
  label?: string;
  value?: string;
  unit?: string;
  delta?: string;
  base?: number;
  items?: ListItem[];
  people?: Person[];
}

export interface CardDef extends RowCardDef {
  x: number;
  y: number;
  h: number;
}

/**
 * Pure layout: places each row's cards left-to-right from PAD with GAP
 * spacing; row `r` sits at `PAD + r * (ROW_H + GAP)`.
 */
export function layoutRows(rows: RowCardDef[][]): CardDef[] {
  const out: CardDef[] = [];
  rows.forEach((row, r) => {
    let x = PAD;
    const y = PAD + r * (ROW_H + GAP);
    for (const card of row) {
      out.push({ ...card, x, y, h: ROW_H });
      x += card.w + GAP;
    }
  });
  return out;
}

/**
 * Pure camera schedule: linear drift from the canvas origin toward the
 * bottom-right, covering `panSpeed` of the available travel by the last frame.
 */
export function panOffset(
  frame: number,
  durationInFrames: number,
  maxX: number,
  maxY: number,
  panSpeed: number,
): { x: number; y: number } {
  const t =
    durationInFrames > 0
      ? Math.min(1, Math.max(0, frame / durationInFrames))
      : 0;
  const p = Math.min(1, Math.max(0, panSpeed));
  return { x: t * maxX * p, y: t * maxY * p };
}

