/** Slow deterministic 0..1 wobble used for gentle in-card motion. */
function noise(i: number, frame: number) {
  return Math.sin(frame / 90 + i * 1.3) * 0.5 + 0.5;
}

/** Deterministic per-bar pseudo value in 0..1. */
function pseudo(i: number, seed: number) {
  return Math.sin(i * 1.7 + seed * 2.3) * 0.5 + 0.5;
}

function ChartBody({
  accent,
  seed,
  frame,
}: {
  accent: string;
  seed: number;
  frame: number;
}) {
  const points: string[] = [];
  for (let i = 0; i < 12; i++) {
    const x = (i / 11) * 100;
    const y =
      24 -
      Math.sin(i * 0.9 + seed * 2.1) * 9 -
      Math.cos(i * 0.5 + seed + frame / 240) * 5;
    points.push(`${x},${y.toFixed(2)}`);
  }
  return (
    <svg
      viewBox="0 0 100 40"
      preserveAspectRatio="none"
      style={{ width: "100%", height: "100%" }}
    >
      <polyline
        points={points.join(" ")}
        fill="none"
        stroke={accent}
        strokeWidth={1.6}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <polyline
        points={`${points.join(" ")} 100,40 0,40`}
        fill={`${accent}14`}
        stroke="none"
      />
    </svg>
  );
}

function BarsBody({
  accent,
  seed,
  frame,
}: {
  accent: string;
  seed: number;
  frame: number;
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-end",
        gap: 6,
        height: "100%",
        width: "100%",
      }}
    >
      {Array.from({ length: 10 }).map((_, i) => {
        const h =
          28 + pseudo(i, seed) * 58 + Math.sin(frame / 80 + i * 0.9) * 3;
        return (
          <div
            // biome-ignore lint/suspicious/noArrayIndexKey: bars are positional and never reorder
            key={i}
            style={{
              flex: 1,
              height: `${h}%`,
              background: i % 3 === 0 ? accent : `${accent}59`,
              borderRadius: 3,
            }}
          />
        );
      })}
    </div>
  );
}

function CodeBody({ tokens, accent }: { tokens: ThemeTokens; accent: string }) {
  const lines = [
    { indent: 0, w: 58, accentLine: true },
    { indent: 1, w: 82, accentLine: false },
    { indent: 1, w: 46, accentLine: false },
    { indent: 2, w: 72, accentLine: false },
    { indent: 2, w: 38, accentLine: true },
    { indent: 1, w: 64, accentLine: false },
    { indent: 0, w: 26, accentLine: false },
  ];
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 9,
        fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
      }}
    >
      {lines.map((l, i) => (
        <div
          // biome-ignore lint/suspicious/noArrayIndexKey: skeleton lines are static and ordered
          key={i}
          style={{
            marginLeft: l.indent * 16,
            width: `${l.w}%`,
            height: 8,
            borderRadius: 3,
            background: l.accentLine
              ? `${accent}59`
              : i % 2 === 0
                ? tokens.skeleton
                : tokens.skeletonSoft,
          }}
        />
      ))}
    </div>
  );
}

function AlertsBody({
  items,
  tokens,
}: {
  items: ListItem[];
  tokens: ThemeTokens;
}) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      {items.map((item, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: rows are static and ordered
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div
            style={{
              width: 8,
              height: 8,
              borderRadius: 4,
              background: TONES[item.tone],
              flexShrink: 0,
            }}
          />
          <div
            style={{
              flex: 1,
              fontSize: 15,
              fontWeight: 500,
              color: tokens.text,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            {item.text}
          </div>
          <div style={{ fontSize: 13, color: tokens.muted }}>{item.meta}</div>
        </div>
      ))}
    </div>
  );
}

function OncallBody({
  people,
  tokens,
  accent,
}: {
  people: Person[];
  tokens: ThemeTokens;
  accent: string;
}) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      {people.map((p, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: rows are static and ordered
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div
            style={{
              width: 34,
              height: 34,
              borderRadius: 17,
              background: `${accent}14`,
              color: accent,
              fontSize: 12,
              fontWeight: 700,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            {p.initials}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                fontSize: 15,
                fontWeight: 600,
                color: tokens.text,
              }}
            >
              {p.name}
              {p.active ? (
                <span
                  style={{
                    width: 6,
                    height: 6,
                    borderRadius: 3,
                    background: TONES.success,
                    display: "inline-block",
                  }}
                />
              ) : null}
            </div>
            <div style={{ fontSize: 13, color: tokens.muted }}>{p.meta}</div>
          </div>
        </div>
      ))}
    </div>
  );
}

function Card({
  card,
  accent,
  tokens,
  index,
  frame,
}: {
  card: CardDef;
  accent: string;
  tokens: ThemeTokens;
  index: number;
  frame: number;
}) {
  const baseStyle: React.CSSProperties = {
    position: "absolute",
    left: card.x,
    top: card.y,
    width: card.w,
    height: card.h,
    borderRadius: 10,
    background: tokens.card,
    border: `1px solid ${tokens.border}`,
    overflow: "hidden",
    padding: 20,
    display: "flex",
    flexDirection: "column",
  };

  const labelEl = card.label ? (
    <div
      style={{
        fontSize: 12,
        fontWeight: 600,
        color: tokens.muted,
        letterSpacing: "0.05em",
        textTransform: "uppercase",
        marginBottom: 10,
      }}
    >
      {card.label}
    </div>
  ) : null;

  if (card.kind === "chart") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div
          style={{
            fontSize: 30,
            fontWeight: 700,
            letterSpacing: "-0.02em",
            color: tokens.text,
          }}
        >
          {card.value}
          {card.unit ? (
            <span style={{ fontSize: 14, color: tokens.muted, marginLeft: 5 }}>
              {card.unit}
            </span>
          ) : null}
        </div>
        <div style={{ flex: 1, marginTop: 10 }}>
          <ChartBody accent={accent} seed={index} frame={frame} />
        </div>
      </div>
    );
  }
  if (card.kind === "bars") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div style={{ flex: 1 }}>
          <BarsBody accent={accent} seed={index} frame={frame} />
        </div>
      </div>
    );
  }
  if (card.kind === "counter") {
    const base = card.base ?? 0;
    const v = base + Math.round(noise(index, frame) * base * 0.015);
    return (
      <div style={baseStyle}>
        {labelEl}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            fontSize: 46,
            fontWeight: 700,
            letterSpacing: "-0.03em",
            color: tokens.text,
          }}
        >
          {v.toLocaleString("en-US")}
        </div>
        {card.delta ? (
          <div style={{ fontSize: 13, fontWeight: 600, color: TONES.success }}>
            {card.delta}
          </div>
        ) : null}
      </div>
    );
  }
  if (card.kind === "stat") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            fontSize: 46,
            fontWeight: 700,
            letterSpacing: "-0.03em",
            color: tokens.text,
          }}
        >
          {card.value}
          {card.unit ? (
            <span style={{ fontSize: 20, color: tokens.muted, marginLeft: 5 }}>
              {card.unit}
            </span>
          ) : null}
        </div>
      </div>
    );
  }
  if (card.kind === "code") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <div style={{ flex: 1, display: "flex", alignItems: "center" }}>
          <div style={{ width: "100%" }}>
            <CodeBody tokens={tokens} accent={accent} />
          </div>
        </div>
      </div>
    );
  }
  if (card.kind === "alerts") {
    return (
      <div style={baseStyle}>
        {labelEl}
        <AlertsBody items={card.items ?? []} tokens={tokens} />
      </div>
    );
  }
  // oncall
  return (
    <div style={baseStyle}>
      {labelEl}
      <OncallBody people={card.people ?? []} tokens={tokens} accent={accent} />
    </div>
  );
}

export function InfiniteBentoPan({
  panSpeed = 0.5,
  accentColor = "#266DF0",
  theme = "light",
  speed = 1,
  className,
}: InfiniteBentoPanProps) {
  const frame = useCurrentFrame() * speed;
  const { durationInFrames, width, height } = useVideoConfig();
  const tokens = BENTO_THEMES[theme] ?? BENTO_THEMES.light;

  const { x: px, y: py } = panOffset(
    frame,
    durationInFrames,
    SUPER_W - width,
    SUPER_H - height,
    panSpeed,
  );

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        background: "transparent",
        overflow: "hidden",
        fontFamily: FONT_FAMILY,
      }}
    >
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: SUPER_W,
          height: SUPER_H,
          transform: `translate(${-px}px, ${-py}px)`,
          willChange: "transform",
        }}
      >
        {CARDS.map((c, i) => (
          <Card
            // biome-ignore lint/suspicious/noArrayIndexKey: card grid is static and ordered
            key={i}
            card={c}
            accent={accentColor}
            tokens={tokens}
            index={i}
            frame={frame}
          />
        ))}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(circle at center, rgba(${tokens.vignetteRgb},0) 42%, rgba(${tokens.vignetteRgb},0.85) 85%, rgb(${tokens.vignetteRgb}) 100%)`,
          pointerEvents: "none",
        }}
      />
    </div>
  );
}
